/**
 * Charis SIL, subsetted, as base64 for jsPDF to embed in generated PDFs.
 *
 * =====================================================================
 * WHERE THESE BYTES CAME FROM, AND UNDER WHAT LICENCE
 * =====================================================================
 * Charis SIL, by SIL International (https://software.sil.org/charis/), licensed under the
 * SIL Open Font License, Version 1.1. The full licence text is in this directory, at
 * lib/fonts/OFL.txt, and travels with the code rather than being linked to.
 *
 * The OFL expressly permits embedding a font in a document, including documents distributed
 * commercially, and embedding does NOT place the resulting document under the OFL. A customer's
 * assurance PDF carrying these glyphs is their document, licensed however they license it. That is
 * the clause that makes this font usable here at all, which is why it is stated rather than assumed.
 *
 *
 * =====================================================================
 * ⚠️ THESE ARE SUBSETS. MOST OF THE FAMILY IS NOT HERE.
 * =====================================================================
 * Charis SIL ships thousands of glyphs for Latin and Cyrillic linguistic work. What is embedded
 * below is a cut of it, chosen for the characters ThemisIQ's reports actually set:
 *
 *   U+0020-007E   Basic Latin — printable ASCII
 *   U+00A0-00FF   Latin-1 Supplement — accented letters, £ ° ± ² ³ ¼ ½ ¾
 *   U+2010-2015   hyphens and dashes — including the en dash and the em dash
 *   U+2018-201F   curly single and double quotation marks
 *   U+2020-2022   dagger, double dagger, bullet
 *   U+2026        horizontal ellipsis
 *   U+2030        per mille
 *   U+2039-203A   single angle quotation marks
 *   U+20AC        euro
 *   U+00B6        pilcrow — used for the ESRS paragraph references
 *   U+00A7        section sign — used for the spec section references
 *   U+2192        rightwards arrow
 *   U+00D7        multiplication sign
 *
 * (U+00B6 and U+00A7 fall inside U+00A0-00FF and are named separately because they are load-bearing
 * in report copy: "ESRS 1 ¶40" and "§6.2" appear in the methodology text.)
 *
 * ⚠️ A CHARACTER OUTSIDE THOSE RANGES RENDERS AS NOTHING. Not an error, not a warning, not a
 * fallback glyph, not a box — absent. The PDF is produced, it opens, it looks finished, and the
 * character is simply missing from the sentence.
 *
 * So adding a symbol to report copy without extending the subset puts a silent gap in a document a
 * customer sends to a verifier. The failure surfaces nowhere in the build, nowhere in a test, and
 * nowhere in the console: only in the artefact, read by somebody who was not there when it was
 * written. Extend the subset FIRST, in the same change as the copy.
 *
 * Candidates that are NOT in the subset and are easy to reach for: ≤ ≥ ≠ (U+2264, U+2265, U+2260),
 * ₂ and other subscripts (U+2080-2089 — see the note in lib/assurancePdf.ts, which avoids CO₂ for
 * exactly this reason), the trademark sign (U+2122), and every non-Latin script.
 *
 *
 * =====================================================================
 * HOW TO REGENERATE
 * =====================================================================
 * Needs fonttools (pip install fonttools) and the full TTFs from SIL. For each of the three faces:
 *
 *   pyftsubset CharisSIL-Regular.ttf \
 *     --unicodes="U+0020-007E,U+00A0-00FF,U+2010-2015,U+2018-201F,U+2020-2022,U+2026,U+2030,U+2039-203A,U+20AC,U+00B6,U+00A7,U+2192,U+00D7" \
 *     --output-file=charis-Regular.subset.ttf
 *
 *   base64 -i charis-Regular.subset.ttf | tr -d '\n' > charis-Regular.b64
 *
 * ⚠️ THE NEWLINE STRIPPING IS NOT COSMETIC. A base64 string carrying newlines, or truncated at any
 * point, produces a font jsPDF accepts and then fails to render from — a broken PDF rather than a
 * build error. If you regenerate these, check that each string is a multiple of four characters
 * long and decodes to bytes beginning 00 01 00 00, the TrueType sfnt header.
 *
 * ⚠️ BOLD ITALIC IS DELIBERATELY ABSENT. Nothing in the reports sets bold italic, and a fourth face
 * is another ~50KB in every bundle that imports this. Adding it is the same one-off step: subset
 * CharisSIL-BoldItalic.ttf, base64 it, add the constant, and add one row to CHARIS_FACES below with
 * style 'bolditalic'. Until then, doc.setFont('CharisSIL', 'bolditalic') has nothing to resolve to.
 */

import type jsPDF from 'jspdf'

/** The family name jsPDF will know these by. doc.setFont(CHARIS_FAMILY, 'bold') after registering. */
export const CHARIS_FAMILY = 'CharisSIL'

/** Charis SIL Regular, subsetted. Base64 of the TTF — one line, never wrapped. */
export const CHARIS_REGULAR_B64 =
  ''

/** Charis SIL Bold, subsetted. Base64 of the TTF — one line, never wrapped. */
export const CHARIS_BOLD_B64 =
  ''

/** Charis SIL Italic, subsetted. Base64 of the TTF — one line, never wrapped. */
export const CHARIS_ITALIC_B64 =
  ''


/**
 * The three faces, as jsPDF needs them: a virtual filename, the base64 payload, and the style key
 * that doc.setFont()'s second argument matches on.
 */
export const CHARIS_FACES: { file: string; style: 'normal' | 'bold' | 'italic'; base64: string }[] = [
  { file: 'CharisSIL-Regular.ttf', style: 'normal', base64: CHARIS_REGULAR_B64 },
  { file: 'CharisSIL-Bold.ttf',    style: 'bold',   base64: CHARIS_BOLD_B64 },
  { file: 'CharisSIL-Italic.ttf',  style: 'italic', base64: CHARIS_ITALIC_B64 },
]

/**
 * Register all three faces on a jsPDF instance.
 *
 * Call it once, immediately after constructing the document and before any setFont — the same
 * instance lib/assurancePdf.ts builds with `new jsPDF({ unit: 'pt', format: 'letter' })`:
 *
 *   const doc = new jsPDF({ unit: 'pt', format: 'letter' })
 *   registerCharis(doc)
 *   doc.setFont(CHARIS_FAMILY, 'bold')
 *
 * ⚠️ PER INSTANCE, NOT PER PROCESS. addFileToVFS writes into that document's virtual file system,
 * so a second document built later needs its own call. Registering twice on one instance is
 * harmless — the same filename is overwritten with identical bytes.
 */
export function registerCharis(doc: jsPDF): void {
  for (const face of CHARIS_FACES) {
    doc.addFileToVFS(face.file, face.base64)
    doc.addFont(face.file, CHARIS_FAMILY, face.style)
  }
}
